action.code:
Float uOffset = 2.0f * u[0] - 1.0f;
Float vOffset = 2.0f * u[1] - 1.0f;

if (uOffset == 0.0f && vOffset == 0.0f) {
    return Point2f(0.0f, 0.0f);
}

Float theta, r;
if (std::abs(uOffset) > std::abs(vOffset)) {
    r = uOffset;
    theta = (vOffset / uOffset) * Pi / 4.0f;
} else {
    r = vOffset;
    theta = (uOffset / vOffset) * Pi / 4.0f;
}

if (uOffset < 0.0f) {
    r = -r;
    theta += Pi;
} else if (vOffset < 0.0f) {
    r = -r;
    theta += Pi;
}

Float cosTheta = std::cos(theta);
Float sinTheta = std::sin(theta);
return Point2f(r * cosTheta, r * sinTheta);
// END_CODE

